    public static function make(string $table, array $dbMap = [], array $inputData = [], array $options = []): array
    {
        $opt = array_merge(['token' => 'token', 'time' => null, 'expire' => 3600, 'identy' => false], $options);
        $accKey = $passKey = $identyKey = null;

        foreach ($dbMap as $inputKey => $dbCol) {
            $lowerKey = strtolower($inputKey);
            if (str_contains($lowerKey, 'email') || str_contains($lowerKey, 'user') || str_contains($lowerKey, 'account') || str_contains($lowerKey, 'login')) {
                $accKey = $inputKey;
            }
            if (str_contains($lowerKey, 'pass') || str_contains($lowerKey, 'pwd') || str_contains($lowerKey, 'secret') || str_contains($lowerKey, 'password')) {
                $passKey = $inputKey;
            }
            if (str_contains($lowerKey, 'identy') || str_contains($lowerKey, 'role') || str_contains($lowerKey, 'type') || str_contains($lowerKey, 'level')) {
                $identyKey = $inputKey;
            }
        }

        $mapKeys = array_keys($dbMap);
        if (!$accKey && count($mapKeys) >= 1)
            $accKey = $mapKeys[0];
        if (!$passKey && count($mapKeys) >= 2)
            $passKey = $mapKeys[1];

        if (!$accKey || !$passKey || !isset($dbMap[$accKey]) || !isset($dbMap[$passKey])) {
            return ['status' => false, 'code' => 500, 'message' => 'Configuration error'];
        }

        $accType = (stripos($accKey, 'email') !== false) ? 'email' : 'string';
        $validationRules = [
            $accKey => [$inputData[$accKey] ?? '', "required|$accType"],
            $passKey => [$inputData[$passKey] ?? '', 'required|string|min:6']
        ];
        if ($identyKey && isset($inputData[$identyKey])) {
            $validationRules[$identyKey] = [$inputData[$identyKey], 'string'];
        }

        $validation = PHVD::check($validationRules);
        if ($validation['result'] !== true || $validation['score'] < 60) {
            return ['status' => false, 'code' => 400, 'message' => 'Validation failed'];
        }

        $selectCols = $dbMap[$accKey] . ', ' . $dbMap[$passKey];
        if ($identyKey) {
            $selectCols .= ', ' . $dbMap[$identyKey];
        }

        $result = PHDB::select($table, $selectCols, [$dbMap[$accKey] => $inputData[$accKey]]);
        if (empty($result) || !isset($result[0]) || empty($result[0])) {
            return ['status' => false, 'code' => 401, 'message' => 'Account not found'];
        }

        $dbUser = $result[0];
        $dbPass = $dbUser[$dbMap[$passKey]] ?? '';
        $inputPass = $inputData[$passKey] ?? '';

        if (!password_verify($inputPass, $dbPass)) {
            return ['status' => false, 'code' => 401, 'message' => 'Invalid password'];
        }

        // Session fixation protection
        if (session_status() === PHP_SESSION_NONE) {
            @session_start();
        }
        session_regenerate_id(true);

        $now = PHTM::getTime();
        $identityValue = PHCO::exists('identity') ? PHCO::get('identity') : base64_encode(($_SERVER['HTTP_USER_AGENT'] ?? 'ua') . '|' . ($_SERVER['REMOTE_ADDR'] ?? 'ip'));

        $payload = ['account' => $inputData[$accKey], 'type' => $table, 'time' => $now, 'identy' => $identityValue];
        $jwtResult = PHJT::create($payload, $opt['expire']);
        if (!$jwtResult['status']) {
            return ['status' => false, 'code' => 500, 'message' => 'Token generation failed'];
        }

        $updateData = [$opt['token'] => $jwtResult['data']];
        if ($opt['time']) {
            $updateData[$opt['time']] = $now;
        }
        if ($opt['identy']) {
            $updateData[$opt['identy']] = $identityValue;
        }

        $updateResult = PHDB::update($table, $updateData, [$dbMap[$accKey] => $inputData[$accKey]]);
        if ($updateResult === false) {
            return ['status' => false, 'code' => 500, 'message' => 'Update failed'];
        } else {
            PHCO::add($table, $jwtResult['data'], $opt['expire'] * 60);
        }

        return ['status' => true, 'code' => 200, 'message' => 'Login Successfully', 'data' => $jwtResult['data']];
    }

    public static function check(string $table, string|array $tokenCol = "token", string $inputToken = null, string|null $identyCol = null): array
    {
        if (is_array($tokenCol)) {
            $columnName = array_key_first($tokenCol);
            $columnValue = $tokenCol[$columnName];
            if (!$columnName && !$columnValue) {
                return ['status' => false, 'code' => 400, 'message' => 'Invalid token name/value'];
            }
            $tokenCol = $columnName;
            $inputToken = $columnValue;
        }
        if (empty($inputToken) || strlen($inputToken) < 30) {
            $inputToken = PHCO::get($table);
        }
        if (empty($inputToken) || strlen($inputToken) < 30) {
            return ['status' => false, 'code' => 400, 'message' => 'Invalid/missing token'];
        }

        $jwtResult = PHJT::verify($inputToken);
        if (!$jwtResult['status']) {
            return ['status' => false, 'code' => 401, 'message' => 'Expired Token'];
        }

        $decoded = $jwtResult['data'];
        $user = PHDB::select($table, $tokenCol . ($identyCol ? ', ' . $identyCol : ''), [$tokenCol => $inputToken]);
        if (empty($user) || !isset($user[0]) || empty($user[0])) {
            return ['status' => false, 'code' => 401, 'message' => 'Token not in DB'];
        }

        $dbUser = $user[0];
        if ($identyCol) {
            $dbIdenty = $dbUser[$identyCol] ?? null;
            $jwtIdenty = $decoded['identy'] ?? null;
            $inputIdenty = PHCO::get('identity') ?? null;
            if ($dbIdenty !== $jwtIdenty || $dbIdenty !== $inputIdenty) {
                return ['status' => false, 'code' => 401, 'message' => 'Identity mismatch'];
            }
        }

        return ['status' => true, 'code' => 200, 'message' => 'Token verified', 'data' => $decoded];
    }

    public static function verifyMake($account = [], $accountRequired = [], $mode = 'OTP', $length = 24, $digits = 6, $time = 180, $offset = 0, $algo = 'sha1', $from = null, $name = null, $cc = '', $bcc = '')
    {
        $validationAccount = PHVD::check($account[key($account)], key($account), $accountRequired);
        if ($validationAccount['type'] === true && $validationAccount['required'] === true) {
            $secret = PHTP::key($length, $mode);
            if ($secret['status'] === false)
                return ['status' => false, 'code' => 400, 'message' => $secret['message']];

            $code = PHTP::code($secret['data'], $mode, $digits, $time, $offset, $algo);
            if ($code['status'] === false)
                return ['status' => false, 'code' => 400, 'message' => $code['message']];

            $message = '<table cellpadding="0" cellspacing="0" border="0" width="100%" bgcolor="#f0f0f0"><tr><td><table cellpadding="0" cellspacing="0" border="0" width="100%" style="max-width:650px;background-color:#ffffff;margin:0 auto;padding:20px;border-radius:10px;box-shadow:0 4px 10px rgba(0,0,0,0.1);"><tr><td style="text-align:center;background-color:#333;padding:20px;"><b style="font-size:32px;font-weight:bold;color:#fff;">' . $name . '</b></td></tr><tr><td style="padding:20px;text-align:center;color:#666;"><h2 style="font-size:24px;color:#333;margin-bottom:20px;">Verification Code</h2><p style="font-size:18px;margin-bottom:30px;">Use the following code to complete your verification:</p><div style="font-size:32px;font-weight:bold;background-color:#2b2b2b;color:#fff;padding:15px;border-radius:5px;letter-spacing:5px;display:inline-block;">' . $code['data'] . '</div></td></tr><tr><td style="margin-top:30px;text-align:center;font-size:12px;color:#777;"><p style="margin:5px 0;">If this email is in your spam folder, please click <strong>Report not spam</strong>.</p><p style="margin:5px 0;">If you did not request this code, please ignore this email.</p></td></tr></table></td></tr></table>';
            $email = PHEM::smtpSend($from, $name, $account[key($account)], $cc, $bcc, 'Verification Code', $message);

            if ($email['status'] === false)
                return ['status' => false, 'code' => 400, 'message' => $email['message']];
            return ['status' => true, 'code' => 200, 'message' => 'Verification code sent'];
        }
        return ['status' => false, 'code' => 400, 'message' => "Invalid account identifier"];
    }

    public static function verifyCheck($table = null, $account = [], $setData = [], $secret = null, $code = 400, $mode = 'OTP', $digits = 6, $time = 180, $offset = 0, $algo = 'sha1')
    {
        $validationAccount = PHVD::check($account[key($account)], "email");
        if ($validationAccount['type'] === true && $validationAccount['required'] === true) {
            $result = PHTP::verify($code, $secret, $mode, $digits, $time, $offset, $algo);
            if ($result['status'] === false)
                return ['status' => false, 'code' => 400, 'message' => $result['message']];

            if ($result['status'] === true && !empty($setData) && $table !== null) {
                $setDB = PHDB::update($table, [key($setData) => current($setData)], $account);
                if ($setDB['status'] === false)
                    return ['status' => false, 'code' => 500, 'message' => $setDB['message']];
            }
            return ['status' => true, 'code' => 200, 'message' => 'Verification Successfully'];
        }
        return ['status' => false, 'code' => 400, 'message' => "Invalid account identifier"];
    }

