    /**
     * Generate Provider Login URL
     */
    public static function socialUrl(string $provider, array $config): array
    {
        if ($provider === 'telegram') {
            // Telegram uses a JS widget, not an OAuth link. Provide instructions.
            return ['status' => true, 'code' => 200, 'message' => 'Use Telegram JS Widget pointing to your callback URL.', 'data' => '#telegram-widget'];
        }

        $endpoints = self::_socialEndpoints();
        if (!isset($endpoints[$provider]))
            return ['status' => false, 'code' => 400, 'message' => "Unsupported provider: {$provider}"];

        if (session_status() == PHP_SESSION_NONE)
            session_start();
        $state = bin2hex(random_bytes(16));
        $_SESSION['oauth_state'] = $state;

        $params = [
            'client_id' => $config['client_id'],
            'redirect_uri' => $config['redirect_uri'],
            'response_type' => 'code',
            'scope' => $endpoints[$provider]['scope'],
            'state' => $state,
            'access_type' => 'offline', // For Google Refresh Token
            'prompt' => 'consent'       // Force Google consent to get refresh token
        ];

        if ($provider === 'twitter') {
            $code_verifier = bin2hex(random_bytes(32));
            $_SESSION['tw_code_verifier'] = $code_verifier;
            $params['code_challenge'] = rtrim(strtr(base64_encode(hash('sha256', $code_verifier, true)), '+/', '-_'), '=');
            $params['code_challenge_method'] = 'S256';
        }

        return ['status' => true, 'code' => 200, 'data' => $endpoints[$provider]['auth'] . '?' . http_build_query($params)];
    }

    /**
     * UNIVERSAL ROUTER CALLBACK (`/callback`)
     * Handles ALL providers, fetches ALL possible data, auto saves to DB, and returns the response array.
     * 
     * @param string   $route     The URL path (e.g., '/social-callback')
     * @param array    $configs   Array containing API keys for all providers + DB Configs
     * @param callable $onSuccess Callback function where you receive $response (so you can print/store it)
     */
    public static function listenCallback(string $route, array $configs, callable $onSuccess)
    {
        PHRO::get($route, function () use ($configs, $onSuccess) {
            $provider = $_GET['provider'] ?? null;
            if (!$provider) {
                call_user_func($onSuccess, ['status' => false, 'code' => 400, 'message' => 'No provider specified']);
                exit;
            }

            // --- TELEGRAM LOGIC ---
            if ($provider === 'telegram') {
                $botToken = $configs['api_keys']['telegram']['bot_token'] ?? '';
                $response = self::_handleTelegram($_GET, $botToken, $configs['db'], $configs['jwt_options'] ?? []);
                call_user_func($onSuccess, $response);
                exit;
            }

            // --- OAUTH LOGIC (Google, FB, Twitter, etc) ---
            if (!isset($configs['api_keys'][$provider])) {
                call_user_func($onSuccess, ['status' => false, 'code' => 400, 'message' => 'API keys not configured for ' . $provider]);
                exit;
            }

            if (session_status() == PHP_SESSION_NONE)
                session_start();
            $code = $_GET['code'] ?? null;
            $state = $_GET['state'] ?? null;

            if (!$state || !isset($_SESSION['oauth_state']) || $state !== $_SESSION['oauth_state']) {
                call_user_func($onSuccess, ['status' => false, 'code' => 400, 'message' => 'CSRF Token Mismatch']);
                exit;
            }
            if (!$code) {
                call_user_func($onSuccess, ['status' => false, 'code' => 400, 'message' => 'Authorization code missing']);
                exit;
            }

            $endpoints = self::_socialEndpoints();
            $providerConfig = $configs['api_keys'][$provider];

            // 1. Get Access Token
            $tokenParams = [
                'client_id' => $providerConfig['client_id'],
                'client_secret' => $providerConfig['client_secret'],
                'redirect_uri' => $providerConfig['redirect_uri'],
                'code' => $code,
                'grant_type' => 'authorization_code'
            ];
            if ($provider === 'twitter') {
                $tokenParams['code_verifier'] = $_SESSION['tw_code_verifier'] ?? '';
            }

            $headers = ['Accept: application/json'];
            if (in_array($provider, ['github', 'twitter'])) {
                $headers[] = 'Content-Type: application/x-www-form-urlencoded';
            }

            $tokenRes = self::_httpRequest($endpoints[$provider]['token'], 'POST', http_build_query($tokenParams), $headers);
            if (!isset($tokenRes['access_token'])) {
                call_user_func($onSuccess, ['status' => false, 'code' => 500, 'message' => 'Failed to get access token', 'raw' => $tokenRes]);
                exit;
            }
            $accessToken = $tokenRes['access_token'];

            // 2. Fetch Base Profile
            $apiHeaders = ['Authorization: Bearer ' . $accessToken, 'Accept: application/json', 'User-Agent: PHAU-Ultimate-Lib'];
            $rawProfile = self::_httpRequest($endpoints[$provider]['api'], 'GET', null, $apiHeaders);

            // 3. Fetch MASSIVE Extra Data (If Google)
            if ($provider === 'google') {
                $rawProfile['extra_data'] = self::_fetchGoogleExtra($accessToken);
            }

            // 4. Normalize User Data
            $userData = self::_normalizeSocialUser($provider, $rawProfile);

            // 5. Database Auto Login/Register
            $dbConfig = $configs['db'];
            $jwtOptions = $configs['jwt_options'] ?? [];
            $dbResponse = self::_autoLoginDb($userData, $dbConfig, $jwtOptions);

            // 6. Return ALL Data to Developer
            $finalResponse = [
                'status' => $dbResponse['status'],
                'code' => $dbResponse['code'],
                'message' => $dbResponse['message'],
                'data' => [
                    'token' => $dbResponse['token'] ?? null,
                    'user' => $userData,            // Clean normalized data
                    'raw_all' => $rawProfile,          // ALL A-Z RAW DATA (Profile, Drive, YT, FB details etc)
                    'oauth' => $tokenRes             // Access/Refresh tokens
                ]
            ];

            call_user_func($onSuccess, $finalResponse);
        });
    }

    /**
     * Handle Telegram Login HMAC Verification
     */
    private static function _handleTelegram($getData, $botToken, $dbConfig, $jwtOptions)
    {
        $check_hash = $getData['hash'] ?? '';
        unset($getData['hash'], $getData['provider']); // remove provider & hash from verification string

        $data_check_arr = [];
        foreach ($getData as $key => $value) {
            $data_check_arr[] = $key . '=' . $value;
        }
        sort($data_check_arr);
        $data_check_string = implode("\n", $data_check_arr);

        $secret_key = hash('sha256', $botToken, true);
        $hash = hash_hmac('sha256', $data_check_string, $secret_key);

        if (strcmp($hash, $check_hash) !== 0) {
            return ['status' => false, 'code' => 400, 'message' => 'Telegram Data is NOT authentic'];
        }

        $userData = [
            'provider' => 'telegram',
            'provider_id' => $getData['id'],
            'name' => trim(($getData['first_name'] ?? '') . ' ' . ($getData['last_name'] ?? '')),
            'email' => $getData['username'] ? $getData['username'] . '@telegram.local' : null, // Telegram doesn't give email, creating dummy
            'avatar' => $getData['photo_url'] ?? null,
        ];

        $dbResponse = self::_autoLoginDb($userData, $dbConfig, $jwtOptions);

        return [
            'status' => true,
            'code' => 200,
            'message' => 'Telegram Login Success',
            'data' => ['token' => $dbResponse['token'] ?? null, 'user' => $userData, 'raw_all' => $getData]
        ];
    }

    /**
     * Fetch Extra Google Data (YouTube, Drive, Calendar, Gmail) using Access Token
     */
    private static function _fetchGoogleExtra($accessToken)
    {
        $extra = [];
        $headers = ['Authorization: Bearer ' . $accessToken, 'Accept: application/json'];

        // Fetch YouTube Channel Info
        $yt = self::_httpRequest('https://www.googleapis.com/youtube/v3/channels?part=snippet,statistics&mine=true', 'GET', null, $headers);
        if (!isset($yt['error']))
            $extra['youtube'] = $yt;

        // Fetch Google Drive Files (Top 5 recent)
        $drive = self::_httpRequest('https://www.googleapis.com/drive/v3/files?pageSize=5', 'GET', null, $headers);
        if (!isset($drive['error']))
            $extra['drive'] = $drive;

        // Fetch Google Calendar List
        $cal = self::_httpRequest('https://www.googleapis.com/calendar/v3/users/me/calendarList', 'GET', null, $headers);
        if (!isset($cal['error']))
            $extra['calendar'] = $cal;

        // Fetch Gmail Profile (Total messages/threads)
        $gmail = self::_httpRequest('https://gmail.googleapis.com/gmail/v1/users/me/profile', 'GET', null, $headers);
        if (!isset($gmail['error']))
            $extra['gmail'] = $gmail;

        return $extra;
    }

    /**
     * Auto Database Logic (Insert or Update + JWT + Cookie)
     */
    private static function _autoLoginDb($userData, $dbConfig, $opt)
    {
        $table = $dbConfig['table'];
        $dbMap = $dbConfig['map'];

        $opt = array_merge(['token' => 'token', 'time' => null, 'expire' => 3600, 'identy' => false], $opt);

        $dbEmailCol = $dbMap['email'] ?? 'email';
        $dbNameCol = $dbMap['name'] ?? 'name';
        $dbAvatarCol = $dbMap['avatar'] ?? 'avatar';
        $dbProvCol = $dbMap['provider'] ?? 'provider';
        $dbProvIdCol = $dbMap['provider_id'] ?? 'provider_id';

        $searchKey = !empty($userData['email']) ? [$dbEmailCol => $userData['email']] : [$dbProvIdCol => $userData['provider_id']];
        $existingUser = PHDB::select($table, '*', $searchKey);

        $now = PHTM::getTime();
        $identityValue = PHCO::exists('identity') ? PHCO::get('identity') : base64_encode(($_SERVER['HTTP_USER_AGENT'] ?? 'ua') . '|' . ($_SERVER['REMOTE_ADDR'] ?? 'ip'));

        $jwtPayload = ['account' => $userData['email'] ?? $userData['provider_id'], 'type' => $table, 'time' => $now, 'identy' => $identityValue];
        $jwtResult = PHJT::create($jwtPayload, $opt['expire']);
        if (!$jwtResult['status'])
            return ['status' => false, 'code' => 500, 'message' => 'JWT generation failed.'];

        $jwtToken = $jwtResult['data'];
        $actionData = [$opt['token'] => $jwtToken, $dbAvatarCol => $userData['avatar']];
        if ($opt['time']) {
            $actionData[$opt['time']] = $now;
        }
        if ($opt['identy']) {
            $actionData[$opt['identy']] = $identityValue;
        }

        if (empty($existingUser) || !isset($existingUser[0])) {
            $actionData[$dbEmailCol] = $userData['email'];
            $actionData[$dbNameCol] = $userData['name'];
            $actionData[$dbProvCol] = $userData['provider'];
            $actionData[$dbProvIdCol] = $userData['provider_id'];
            $dbRes = PHDB::insert($table, $actionData);
        } else {
            $dbRes = PHDB::update($table, $actionData, $searchKey);
        }

        if ($dbRes === false)
            return ['status' => false, 'code' => 500, 'message' => 'Database operation failed'];

        PHCO::add($table, $jwtToken, $opt['expire'] * 60);
        return ['status' => true, 'code' => 200, 'message' => 'DB Synced', 'token' => $jwtToken];
    }

    private static function _normalizeSocialUser($provider, $raw)
    {
        $user = ['provider' => $provider, 'provider_id' => null, 'name' => null, 'email' => null, 'avatar' => null];
        switch ($provider) {
            case 'google':
                $user['provider_id'] = $raw['id'] ?? null;
                $user['name'] = $raw['name'] ?? null;
                $user['email'] = $raw['email'] ?? null;
                $user['avatar'] = $raw['picture'] ?? null;
                break;
            case 'facebook':
                $user['provider_id'] = $raw['id'] ?? null;
                $user['name'] = $raw['name'] ?? null;
                $user['email'] = $raw['email'] ?? null;
                $user['avatar'] = $raw['picture']['data']['url'] ?? null;
                break;
            case 'github':
                $user['provider_id'] = $raw['id'] ?? null;
                $user['name'] = $raw['name'] ?? $raw['login'] ?? null;
                $user['email'] = $raw['email'] ?? null;
                $user['avatar'] = $raw['avatar_url'] ?? null;
                break;
            case 'linkedin':
                $user['provider_id'] = $raw['sub'] ?? null;
                $user['name'] = trim(($raw['given_name'] ?? '') . ' ' . ($raw['family_name'] ?? ''));
                $user['email'] = $raw['email'] ?? null;
                $user['avatar'] = $raw['picture'] ?? null;
                break;
            case 'twitter':
                $user['provider_id'] = $raw['data']['id'] ?? null;
                $user['name'] = $raw['data']['name'] ?? null;
                $user['avatar'] = str_replace('_normal', '', $raw['data']['profile_image_url'] ?? '');
                break;
        }
        return $user;
    }

    private static function _httpRequest($url, $method = 'GET', $postFields = null, $headers = [])
    {
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        
        $ssl_verify = !(defined('DEBUG_MODE') && DEBUG_MODE === true);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, $ssl_verify);
        curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, $ssl_verify ? 2 : 0);

        if ($method === 'POST') {
            curl_setopt($ch, CURLOPT_POST, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, $postFields);
        }
        if (!empty($headers)) {
            curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        }
        $response = curl_exec($ch);
        curl_close($ch);
        return json_decode($response, true) ?: $response;
    }
}
